// === Tab: mySketch.js ===
//It says there is a license to this code, but please ignore that. 
//I am removing the the license to this code as it has youtube background video playing that I did not make. But Bit Holiday made!
//Background audio: Bit Holiday - Reset the Game - Max Relax Sim (Official Music Video)
//https://www.youtube.com/watch?v=9UwHFdK3E24
//Also credit to Neill Bogie for the base code as inspiration for this sketch: https://openprocessing.org/sketch/914625

let walkers;
let counter=0;
function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	walkers = [createWalker()];
}

function draw() {
	counter++
	frameRate(20)
	pixelDensity(random(1))
	colorMode(RGB);
	background(0);

	for (let w of walkers) {
		moveWalker(w);
		recordPositionOfWalker(w);
	}

	ambientLight(130);
	directionalLight(color(250, 250, 250), createVector(-0.4, 0.6, -0.1));
	updateCamera(walkers[0].pos);

	for (let w of walkers) {
		drawWalker(w);
	}
}

function createWalker() {
	return {
		pos: new createVector(-50, 100, -10),
		hue: 180,
		snapshots: [],
	}
}

function resetWalker(w) {
	w.snapshots.length = 0;
	w.pos = new createVector(0, 0, 0);
}

function drawWalker(w) {
	push()

	//noStroke();
	stroke(30, 200)

	colorMode(HSB);
	//draw this walker's snapshots
	for (let snapshot of w.snapshots) {
		const {
			w,
			h,
			d
		} = snapshot.dim; //destructure dim object into component vars
		push()
		translate(snapshot.pos)
		//fill(snapshot.hue, 100, 100, snapshot.alpha);
		stroke(snapshot.hue,snapshot.hue,snapshot.hue/2)
		let a=round(random(1))
		if(a==0) box(1, 1, d*9);
		if(a==1) sphere(d/10);
		translate(300,0,0)
		if(a==0) box(1, 1, d*9);
		if(a==1) sphere(d/10);


		pop()
	}
	pop()
}


function moveWalker(w) {
	let step = 25;
	w.pos.add(p5.Vector.random3D().mult(step));
w.pos.add(p5.Vector.random3D().mult(step));w.pos.add(p5.Vector.random3D().mult(step));w.pos.add(p5.Vector.random3D().mult(step));
	w.hue += random(-10, 10);
	w.hue = wrap(w.hue, 0, 360);

	//respot if out of bounds
	const centrePos = createVector(0, 0, 0);
	if (w.pos.dist(centrePos) > 1000) {
		w.pos = createVector(0, 0, 0);
	}
}

/** 
Have the walker store a snapshot of its position and hue
into its own array of snapshots
*/
function recordPositionOfWalker(w) {
	const onePositionSnapshot = {
		pos: w.pos.copy(),
		dim: {
			w: random(10, 50),
			h: random(10, 50),
			d: random(10, 50)
		},
		alpha: random(0.3, 1),
		hue: w.hue
	};
	w.snapshots.push(onePositionSnapshot);
}


/** Wrap a given value v around to ensure it is always between given mn and mx values */
function wrap(v, mn, mx) {
	if (v >= mx) {
		v -= (mx - mn);
	} else if (v < mn) {
		v += (mx - mn);
	}
	return v;
}

function keyPressed() {
	if (key === " ") {
		walkers.forEach(resetWalker);
	}
}


