let myCamera;
let cameraTargetPos;

function setupCamera() {
	myCamera = createCamera();
	cameraTargetPos = createVector();
}

function updateCamera(walkerPos) {

	cameraTargetPos.lerp(walkerPos.x, walkerPos.y, walkerPos.z, 0.02);
	orbitControl(5, 5, 0.1);

	myCamera.lookAt(cameraTargetPos.x, cameraTargetPos.y, cameraTargetPos.z);
}

